def run_causal_discovery(X: np.ndarray) -> GeneralGraph:
    """
    Input:  X of shape (n_samples, n_variables), integer-encoded discrete data
    Output: estimated CPDAG as causallearn.graph.GeneralGraph.GeneralGraph

    Algorithm: Greedy Equivalence Search with Iterative DAG Refinement (GES-IDR)

    Novelty:
    1. Two-phase search: Phase 1 runs standard GES in CPDAG space (efficient,
       globally oriented). Phase 2 converts the result to a DAG and performs
       additional local refinement in DAG space using BDeu scoring, allowing
       escape from CPDAG-space local optima.
    2. The DAG refinement considers add/delete/reverse moves even for edges
       not in the CPDAG, effectively recovering missed adjacencies.
    3. The final CPDAG is obtained by converting the refined DAG, ensuring
       all Meek-compatible orientations are recovered.
    """
    n_samples, d = X.shape
    nodes = [GraphNode(f"X{i + 1}") for i in range(d)]

    # ---- Phase 1: GES in CPDAG space ----
    result = ges(
        X,
        score_func="local_score_BDeu",
        parameters={"sample_prior": 1.0, "structure_prior": 1.0},
    )
    G_ges = result["G"]

    # ---- Phase 2: Convert GES CPDAG to DAG ----
    # Extract adjacency from GES result
    adj_ges = np.zeros((d, d), dtype=int)
    for i in range(d):
        for j in range(d):
            if i != j:
                edge = G_ges.get_edge(nodes[i], nodes[j])
                if edge is not None:
                    # Check direction: if directed i -> j
                    if edge.direction == 1:  # arrow from nodes[i] to nodes[j] (endpoint.ARROW)
                        adj_ges[i, j] = 1
                    elif edge.direction == 2:  # arrow from nodes[j] to nodes[i]
                        adj_ges[j, i] = 1
                    elif edge.direction == 0:  # undirected (Circle-Circle)
                        adj_ges[i, j] = 1
                        adj_ges[j, i] = 1

    # Orient undirected edges into a DAG using topological ordering + BDeu scores
    # First, get a topological order by orienting undirected edges
    score_func = LocalScoreClass(
        data=X, local_score_fun=local_score_BDeu, parameters=None
    )

    # For undirected edges, orient using pairwise BDeu comparison
    adj = adj_ges.copy()
    for i in range(d):
        for j in range(i + 1, d):
            if adj[i, j] == 1 and adj[j, i] == 1:
                score_i_to_j = score_func.score(j, [i])
                score_j_to_i = score_func.score(i, [j])
                if score_i_to_j < score_j_to_i - 0.01:
                    adj[j, i] = 0
                elif score_j_to_i < score_i_to_j - 0.01:
                    adj[i, j] = 0
                # else keep undirected (small difference)

    # Ensure acyclicity via cycle breaking
    for _ in range(d):
        # Detect cycle
        visited = [0] * d
        parent = [-1] * d
        cycle_found = False

        def dfs(u):
            nonlocal cycle_found
            if cycle_found:
                return
            visited[u] = 1
            for v in range(d):
                if adj[u, v] == 1 and adj[v, u] == 0:
                    if visited[v] == 1:
                        # Found cycle, break by reversing u -> v
                        adj[u, v] = 0
                        adj[v, u] = 1
                        cycle_found = True
                        return
                    elif visited[v] == 0:
                        dfs(v)
            visited[u] = 2

        for u in range(d):
            if visited[u] == 0:
                dfs(u)

        if not cycle_found:
            break

    # Now adj should be a DAG (or close to one)
    # ---- Phase 3: DAG refinement ----
    local_scores = np.zeros(d)
    for j in range(d):
        local_scores[j] = score_func.score(j, sorted(np.where(adj[:, j] == 1)[0].tolist()))

    def has_path(src, tgt):
        visited = set()
        stack = [src]
        while stack:
            node = stack.pop()
            if node == tgt:
                return True
            if node in visited:
                continue
            visited.add(node)
            for c in range(d):
                if adj[node, c] == 1 and c not in visited:
                    stack.append(c)
        return False

    # Multiple refinement passes
    for _ in range(2):
        improved = True
        while improved:
            improved = False
            best_delta = 0.0
            best_op = None

            for i in range(d):
                for j in range(d):
                    if i == j:
                        continue

                    if adj[i, j] == 0 and adj[j, i] == 0:
                        # ADD i -> j (check acyclic)
                        if not has_path(j, i):
                            pj_new = sorted(
                                np.where(adj[:, j] == 1)[0].tolist() + [i]
                            )
                            new_sj = score_func.score(j, pj_new)
                            delta = new_sj - local_scores[j]
                            if delta < best_delta - 1e-8:
                                best_delta = delta
                                best_op = ("add", i, j)

                    elif adj[i, j] == 1:
                        # DELETE i -> j
                        pj_new = [
                            p for p in np.where(adj[:, j] == 1)[0] if p != i
                        ]
                        new_sj = score_func.score(j, sorted(pj_new))
                        delta = new_sj - local_scores[j]
                        if delta < best_delta - 1e-8:
                            best_delta = delta
                            best_op = ("delete", i, j)

                        # REVERSE i -> j to j -> i
                        adj[i, j] = 0
                        if not has_path(i, j):
                            pj_del = sorted(np.where(adj[:, j] == 1)[0].tolist())
                            new_sj = score_func.score(j, pj_del)
                            pi_new = sorted(
                                np.where(adj[:, i] == 1)[0].tolist() + [j]
                            )
                            new_si = score_func.score(i, pi_new)
                            delta = (
                                (new_sj - local_scores[j])
                                + (new_si - local_scores[i])
                            )
                            if delta < best_delta - 1e-8:
                                best_delta = delta
                                best_op = ("reverse", i, j)
                        adj[i, j] = 1

            if best_op is not None:
                op_type, i, j = best_op
                if op_type == "add":
                    adj[i, j] = 1
                elif op_type == "delete":
                    adj[i, j] = 0
                elif op_type == "reverse":
                    adj[i, j] = 0
                    adj[j, i] = 1
                local_scores[j] = score_func.score(
                    j, sorted(np.where(adj[:, j] == 1)[0].tolist())
                )
                if op_type == "reverse":
                    local_scores[i] = score_func.score(
                        i, sorted(np.where(adj[:, i] == 1)[0].tolist())
                    )
                improved = True

    # ---- Phase 4: Final CPDAG ----
    G = GeneralGraph(nodes)
    for i in range(d):
        for j in range(d):
            if adj[i, j] == 1 and adj[j, i] == 0:
                G.add_directed_edge(nodes[i], nodes[j])

    G = dag2cpdag(G)
    return G
